mapper.select:
SELECT
(
SELECT COUNT(*)
FROM ORDERS O
WHERE O.USER_ID = #{userId}
) AS orderCount,

(
SELECT COALESCE(U.POINT, 0)
FROM USER U
WHERE U.USER_ID = #{userId}
) AS pointAmount,

(
SELECT COUNT(*)
FROM USER_COUPON UC
WHERE UC.USER_ID = #{userId}
AND UC.USED_YN = 'N'
AND UC.STATUS = 'AVAILABLE'
AND (UC.EXPIRED_AT IS NULL OR UC.EXPIRED_AT >= NOW())
) AS couponCount,

(
SELECT COUNT(*)
FROM WISHLIST W
WHERE W.USER_ID = #{userId}
) AS wishlistCount,

(
SELECT COUNT(*)
FROM USER_COUPON
WHERE USER_ID = #{userId}
AND USED_YN = 'N'
AND EXPIRED_AT >= CURDATE()
AND EXPIRED_AT < DATE_ADD(CURDATE(), INTERVAL 4 DAY)
) AS expiringCouponCount

SELECT COUNT(*)
FROM USER_COUPON
WHERE USER_ID = #{userId}
